import unittest

from ports import DEFAULT_PORT, normalize_port


class PortTests(unittest.TestCase):
    def test_none_uses_default(self):
        self.assertEqual(normalize_port(None), DEFAULT_PORT)

    def test_blank_string_uses_default(self):
        self.assertEqual(normalize_port("   "), DEFAULT_PORT)

    def test_numeric_string_is_preserved(self):
        self.assertEqual(normalize_port("9000"), 9000)

    def test_non_string_numeric_value_is_preserved(self):
        self.assertEqual(normalize_port(4.5), 4)


if __name__ == "__main__":
    unittest.main()
